def count_weekend_days_breakdown(year, month):
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    dim = days_in_months[month - 1]
    if month == 2 and is_leap(year):
        dim = 29

    def weekday(y, m, d):
        if m <= 2:
            y -= 1
            m += 12
        k = y % 100
        j = y // 100
        h = (d + (13 * (m + 1)) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
        return (h + 5) % 7

    saturdays = sum(1 for day in range(1, dim + 1) if weekday(year, month, day) == 5)
    sundays = sum(1 for day in range(1, dim + 1) if weekday(year, month, day) == 6)
    return (saturdays, sundays)

